          "stage": "benefit",
          "focus": "把手端拿体验",
          "sentences": [
            {
              "display_text": "杯身带把手，端起来的时候手指穿过把手，握着比较稳当。",
              "spoken_text": "杯身带把手，端起来的时候手指穿过把手，握着比较稳当。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
