        {
          "stage": "benefit",
          "focus": "陶瓷材质手感",
          "sentences": [
            {
              "display_text": "陶瓷材质摸上去比较细腻，放在桌上也有分量感。",
              "spoken_text": "陶瓷材质摸上去比较细腻，放在桌上也有分量感。",
